        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('10011111-0000-4000-8000-000000000001', 'When magnesium ribbon burns in air with a dazzling white flame, it forms a white powder of:', '{"A":"Magnesium carbonate","B":"Magnesium oxide","C":"Magnesium hydroxide","D":"Magnesium nitride"}'::jsonb, 'B', 'MCQ', 'Science', 'Chemical Reactions and Equations', 1, '2Mg + O₂ -> 2MgO forms white magnesium oxide ash.', NULL, NULL, '2Mg + O₂ -> 2MgO forms white magnesium oxide ash.', 'EASY', true),
        ('10011111-0000-4000-8000-000000000002', 'In the reaction PbO + C -> Pb + CO, the substance reduced is:', '{"A":"C","B":"CO","C":"PbO","D":"Pb"}'::jsonb, 'C', 'MCQ', 'Science', 'Chemical Reactions and Equations', 1, 'PbO loses oxygen to form Pb, so PbO is reduced.', NULL, NULL, 'PbO loses oxygen to form Pb, so PbO is reduced.', 'EASY', true),
        ('10011111-0000-4000-8000-000000000003', 'Which reaction represents an exothermic double displacement reaction forming a yellow precipitate?', '{"A":"AgNO₃ + NaCl","B":"Pb(NO₃)₂ + 2KI","C":"BaCl₂ + Na₂SO₄","D":"CuSO₄ + Fe"}'::jsonb, 'B', 'MCQ', 'Science', 'Chemical Reactions and Equations', 1, 'Pb(NO₃)₂ + 2KI -> PbI₂(s, yellow) + 2KNO₃.', NULL, NULL, 'Pb(NO₃)₂ + 2KI -> PbI₂(s, yellow) + 2KNO₃.', 'EASY', true),
        ('10011111-0000-4000-8000-000000000004', 'Why are potato chips packets flushed with nitrogen gas?', '{"A":"To add crispiness","B":"To prevent oxidation and rancidity of oils","C":"To increase weight","D":"To kill microbes by freezing"}'::jsonb, 'B', 'MCQ', 'Science', 'Chemical Reactions and Equations', 1, 'Nitrogen is an inert antioxidant gas that prevents fat/oil oxidation (rancidity).', NULL, NULL, 'Nitrogen is an inert antioxidant gas that prevents fat/oil oxidation (rancidity).', 'EASY', true),
        ('10011111-0000-4000-8000-000000000005', 'Thermal decomposition of calcium carbonate yields CaO and CO₂. CaO is commonly called:', '{"A":"Slaked lime","B":"Quick lime","C":"Limestone","D":"Baking soda"}'::jsonb, 'B', 'MCQ', 'Science', 'Chemical Reactions and Equations', 1, 'CaO is quick lime; Ca(OH)₂ is slaked lime.', NULL, NULL, 'CaO is quick lime; Ca(OH)₂ is slaked lime.', 'EASY', true),
        ('10011111-0000-4000-8000-000000000006', 'Electrolysis of water produces H₂ and O₂ gases in the volume ratio:', '{"A":"1 : 1","B":"2 : 1","C":"1 : 2","D":"4 : 1"}'::jsonb, 'B', 'MCQ', 'Science', 'Chemical Reactions and Equations', 1, '2H₂O -> 2H₂ + O₂ gives 2 volumes of H₂ at cathode and 1 volume of O₂ at anode.', NULL, NULL, '2H₂O -> 2H₂ + O₂ gives 2 volumes of H₂ at cathode and 1 volume of O₂ at anode.', 'EASY', true),
        ('10011111-0000-4000-8000-000000000007', 'Respiration is classified as an exothermic process because:', '{"A":"Oxygen is absorbed","B":"Glucose oxidises in cells releasing heat energy","C":"Carbon dioxide is exhaled","D":"Water evaporates"}'::jsonb, 'B', 'MCQ', 'Science', 'Chemical Reactions and Equations', 1, 'C₆H₁₂O₆ + 6O₂ -> 6CO₂ + 6H₂O + Energy.', NULL, NULL, 'C₆H₁₂O₆ + 6O₂ -> 6CO₂ + 6H₂O + Energy.', 'EASY', true),
        ('10011111-0000-4000-8000-000000000008', 'Sunlight decomposition of silver chloride turns white AgCl into:', '{"A":"Blue AgOH","B":"Grey metallic silver","C":"Black Ag₂S","D":"Yellow AgI"}'::jsonb, 'B', 'MCQ', 'Science', 'Chemical Reactions and Equations', 1, '2AgCl(s) -> 2Ag(s, grey) + Cl₂(g) in sunlight.', NULL, NULL, '2AgCl(s) -> 2Ag(s, grey) + Cl₂(g) in sunlight.', 'EASY', true),
        ('10011111-0000-4000-8000-000000000009', 'Assertion (A): Silver articles turn black when kept in open air for a few days.
        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('10011111-0000-4000-8000-0000000000c9', 'Pentane has the molecular formula C₅H₁₂. How many covalent bonds are present in one molecule of pentane?', '{"A":"5","B":"12","C":"16","D":"17"}'::jsonb, 'C', 'MCQ', 'Science', 'Carbon and its Compounds', 1, 'Option (C) is correct. Pentane has 4 C–C single bonds and 12 C–H single bonds, giving 4 + 12 = 16 covalent bonds.', 'Option (C): 4 C–C + 12 C–H = 16 covalent bonds [1 Mark]', NULL, 'Examiner Tip: For any alkane CₙH₂ₙ₊₂, total covalent bonds = (n-1) + (2n+2) = 3n + 1. For n=5, 3(5)+1 = 16. | Common Pitfall: Counting only C–H bonds (12) or forgetting one C–C bond.', 'EASY', true),
        ('10011111-0000-4000-8000-0000000000ca', 'Which chamber of the human heart receives oxygenated blood directly from the lungs via pulmonary veins?', '{"A":"Right atrium","B":"Right ventricle","C":"Left atrium","D":"Left ventricle"}'::jsonb, 'C', 'MCQ', 'Science', 'Life Processes', 1, 'Option (C) is correct. Oxygenated blood from the lungs enters the left atrium through the pulmonary veins before passing into the left ventricle.', 'Identify Left Atrium as receiver of oxygenated blood from lungs [1 Mark]', NULL, 'Examiner Tip: Left side of heart always carries oxygenated blood; Atria always receive blood. | Common Pitfall: Confusing pulmonary vein with pulmonary artery or atrium with ventricle.', 'EASY', true),
        ('10011111-0000-4000-8000-0000000000cb', 'During vigorous exercise, muscle cramps occur due to accumulation of:', '{"A":"Ethanol and CO₂","B":"Lactic acid","C":"Pyruvate","D":"Acetic acid"}'::jsonb, 'B', 'MCQ', 'Science', 'Life Processes', 1, 'Option (B) is correct. Lack of oxygen in human skeletal muscle cells converts 3-carbon pyruvate into lactic acid (3-carbon molecule), causing cramps.', 'Identify lactic acid accumulation during anaerobic muscle respiration [1 Mark]', NULL, 'Examiner Tip: Distinguish yeast fermentation (ethanol + CO₂) from muscle lack-of-O₂ pathway (lactic acid only). | Common Pitfall: Selecting ethanol for human muscles.', 'EASY', true),
        ('10011111-0000-4000-8000-0000000000cc', 'Growth of a pollen tube towards the ovule inside the pistil is an example of:', '{"A":"Phototropism","B":"Geotropism","C":"Chemotropism","D":"Hydrotropism"}'::jsonb, 'C', 'MCQ', 'Science', 'Control and Coordination', 1, 'Option (C) is correct. Pollen tube grows in response to chemical substances secreted by the ovule, demonstrating chemotropism.', 'Identify Chemotropism [1 Mark]', NULL, 'Examiner Tip: Remember NCERT example: chemotropism = pollen tube growth towards ovule. | Common Pitfall: Selecting geotropism because the tube grows downwards.', 'EASY', true),
        ('10011111-0000-4000-8000-0000000000cd', 'At the synapse between two neurons, electrical impulse is converted into:', '{"A":"Mechanical wave","B":"Chemical signal (neurotransmitter)","C":"Thermal energy","D":"Magnetic pulse"}'::jsonb, 'B', 'MCQ', 'Science', 'Control and Coordination', 1, 'Option (B) is correct. At the axon terminal, the electrical impulse triggers release of chemicals (neurotransmitters) that cross the synaptic gap and start a similar electrical impulse in the next neuron dendrite.', 'Option (B) identifying chemical signal conversion at synapse [1 Mark]', NULL, 'Examiner Tip: Synapse ensures unidirectional flow of nerve impulses. | Common Pitfall: Stating impulse jumps directly as electricity across the gap.', 'EASY', true),
        ('10011111-0000-4000-8000-0000000000ce', 'Which organism reproduces by multiple fission inside a protective cyst under unfavourable conditions?', '{"A":"Amoeba","B":"Leishmania","C":"Plasmodium","D":"Spirogyra"}'::jsonb, 'C', 'MCQ', 'Science', 'How do Organisms Reproduce', 1, 'Option (C) is correct. Plasmodium (malarial parasite) divides into many daughter cells simultaneously by multiple fission.', 'Identify Plasmodium as multiple fission example [1 Mark]', NULL, 'Examiner Tip: Amoeba = binary fission (any plane); Leishmania = binary fission (definite orientation); Plasmodium = multiple fission. | Common Pitfall: Confusing Leishmania with Plasmodium.', 'EASY', true),
        ('10011111-0000-4000-8000-0000000000cf', 'When pure tall pea plants (TT) are crossed with pure dwarf pea plants (tt), the phenotypic ratio in the F₂ generation is:', '{"A":"1 : 2 : 1","B":"3 : 1","C":"9 : 3 : 3 : 1","D":"2 : 1"}'::jsonb, 'B', 'MCQ', 'Science', 'Heredity', 1, 'Option (B) is correct. In F₂ generation, 75% plants are tall (1 TT + 2 Tt) and 25% are dwarf (1 tt), giving a phenotypic ratio of 3 : 1.', 'Identify 3:1 phenotypic ratio in F2 monohybrid cross [1 Mark]', NULL, 'Examiner Tip: Phenotypic ratio = 3:1; Genotypic ratio = 1:2:1. | Common Pitfall: Giving genotypic ratio 1:2:1 when phenotypic ratio is asked.', 'EASY', true),
        ('10011111-0000-4000-8000-0000000000d0', 'A spherical mirror produces a magnification of m = -2. The image formed is:', '{"A":"Virtual, erect and diminished","B":"Real, inverted and enlarged","C":"Virtual, erect and enlarged","D":"Real, inverted and same size"}'::jsonb, 'B', 'MCQ', 'Science', 'Light', 1, 'Option (B) is correct. Negative magnification (m < 0) denotes a real and inverted image; |m| = 2 > 1 indicates the image is magnified (enlarged).', 'Negative sign = real/inverted, |m|>1 = enlarged [1 Mark]', NULL, 'Examiner Tip: Always split m into sign (+ virtual/erect, - real/inverted) and magnitude (>1 enlarged, <1 diminished). | Common Pitfall: Ignoring the minus sign.', 'EASY', true),
        ('10011111-0000-4000-8000-0000000000d1', 'Why do stars appear to twinkle at night whereas planets do not?', '{"A":"Planets emit steady light","B":"Stars undergo continuous atmospheric refraction as point sources, while planets act as extended sources","C":"Stars undergo total internal reflection","D":"Planets absorb blue light completely"}'::jsonb, 'B', 'MCQ', 'Science', 'Human Eye', 1, 'Option (B) is correct. Stars are distant point-sized sources whose apparent path fluctuates with changing air refractive indices. Planets are much closer extended sources (collection of many point sources) so total variation averages out to zero.', 'Point source atmospheric refraction vs extended source averaging [1 Mark]', NULL, 'Examiner Tip: Must mention both "point source" and "average variation becomes zero" for extended planets. | Common Pitfall: Saying stars produce flickering nuclear light.', 'EASY', true),
        ('10011111-0000-4000-8000-0000000000d2', 'Assertion (A): Reaction of zinc oxide with carbon (ZnO + C → Zn + CO) is a redox reaction.
